body{font-family:var(--ui-font);color:var(--ui-text);background:var(--ui-background)}
h1{font-size:var(--ui-size-title);font-weight:600;margin:0 0 var(--ui-space-2)}
.muted{color:var(--ui-text-secondary);font-size:var(--ui-size-secondary);margin:var(--ui-space-1) 0}
label{display:block;margin-bottom:var(--ui-space-1)}
.row{display:flex;gap:var(--ui-space-2)}
input[type=text]{flex:1;min-width:0;min-height:var(--ui-target);padding:0 var(--ui-space-3);border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);font:inherit;background:var(--ui-surface);color:var(--ui-text)}
button{min-height:var(--ui-target);padding:0 var(--ui-space-4);border:1px solid var(--ui-accent);background:var(--ui-accent);color:#fff;border-radius:var(--ui-radius-control);font:inherit;cursor:pointer}
