const listEl=document.getElementById('list');
const input=document.getElementById('newItem');
const msg=document.getElementById('msg');
const emptyEl=document.getElementById('empty');
const clearBtn=document.getElementById('clearBtn');
const countEl=document.getElementById('count');
let items=[];let revs={};
function say(t,bad){msg.textContent=t;msg.className=bad?'muted err':'muted';}
async function load(){
try{const r=await tessera.call('data.read',{});items=r.data.items||[];revs=r.revisions.items||{};render();}
catch(e){say('Could not load the list.',true);}
}
async function patch(ops,okText){
try{await tessera.call('data.patch',{operations:ops});await load();if(okText)say(okText);}
catch(e){say('That change did not go through. Please try again.',true);await load();}
}
function render(){
listEl.textContent='';
for(const it of items){
const li=document.createElement('li');
if(it.done)li.className='done';
const lab=document.createElement('label');
const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!it.done;
const nm=document.createElement('span');nm.className='name';nm.textContent=it.name;
lab.append(cb,nm);
cb.addEventListener('change',()=>patch([{op:'replace',collection:'items',id:it.id,revisionCount:revs[it.id],fields:{done:cb.checked}}]));
const del=document.createElement('button');del.type='button';del.className='del';del.textContent='Remove';
del.setAttribute('aria-label','Remove '+it.name);
del.addEventListener('click',()=>patch([{op:'remove',collection:'items',id:it.id,revisionCount:revs[it.id]}],it.name+' removed.'));
li.append(lab,del);listEl.append(li);
}
const doneN=items.filter(i=>i.done).length;
emptyEl.hidden=items.length>0;
clearBtn.hidden=doneN===0;
countEl.textContent=items.length?doneN+' of '+items.length+' ticked':'';
}
function add(){
const v=input.value.trim();
if(!v){say('Type an item first.',true);input.focus();return;}
input.value='';
patch([{op:'add',collection:'items',record:{name:v,done:false}}],v+' added.');
input.focus();
}
document.getElementById('addBtn').addEventListener('click',add);
input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
clearBtn.addEventListener('click',()=>{
const ops=items.filter(i=>i.done).map(i=>({op:'remove',collection:'items',id:i.id,revisionCount:revs[i.id]}));
if(ops.length)patch(ops,'Ticked items removed.');
});
load();

const keys=[['C','clear','AC','op'],['⌫','back','Delete last digit','op'],['%','%','Percent','op'],['÷','/','Divide','op'],['7'],['8'],['9'],['×','*','Multiply','op'],['4'],['5'],['6'],['−','-','Subtract','op'],['1'],['2'],['3'],['+','+','Add','op'],['0'],['.'],['=','=','Equals','eq'],['±','neg','Change sign','op']];
let cur='0',prev=null,op=null,fresh=false;
const out=document.getElementById('out'),expr=document.getElementById('expr'),msg=document.getElementById('msg');
const sym={'/':'÷','*':'×','-':'−','+':'+'};
function show(){out.textContent=cur;expr.textContent=op?prev+' '+sym[op]:''}
function calc(a,b,o){a=parseFloat(a);b=parseFloat(b);let r;if(o==='+')r=a+b;else if(o==='-')r=a-b;else if(o==='*')r=a*b;else{if(b===0)return null;r=a/b}return String(parseFloat(r.toPrecision(12)))}
function press(k){msg.textContent='';
if(/^[0-9]$/.test(k)){if(fresh||cur==='0'){cur=k;fresh=false}else cur+=k}
else if(k==='.'){if(fresh){cur='0.';fresh=false}else if(!cur.includes('.'))cur+='.'}
else if(k==='clear'){cur='0';prev=null;op=null;fresh=false}
else if(k==='back'){if(!fresh){cur=cur.length>1?cur.slice(0,-1):'0';if(cur==='-')cur='0'}}
else if(k==='neg'){if(cur!=='0')cur=cur[0]==='-'?cur.slice(1):'-'+cur}
else if(k==='%'){cur=String(parseFloat((parseFloat(cur)/100).toPrecision(12)))}
else if(k==='='){if(op){const r=calc(prev,cur,op);if(r===null){msg.textContent='You can’t divide by zero.';cur='0'}else cur=r;prev=null;op=null;fresh=true}}
else{if(op&&!fresh){const r=calc(prev,cur,op);if(r===null){msg.textContent='You can’t divide by zero.';cur='0';op=null;prev=null;show();return}cur=r}
prev=cur;op=k;fresh=true}
show()}
const box=document.getElementById('keys');
for(const d of keys){const b=document.createElement('button');b.type='button';b.textContent=d[0];const k=d[1]||d[0];if(d[2])b.setAttribute('aria-label',d[2]);if(d[3])b.className=d[3];b.addEventListener('click',()=>press(k));box.appendChild(b)}
document.addEventListener('keydown',e=>{if(e.target.tagName==='BUTTON'&&(e.key==='Enter'||e.key===' '))return;const k=e.key;if(/^[0-9.+\-*\/%]$/.test(k))press(k);else if(k==='Enter'||k==='='){e.preventDefault();press('=')}else if(k==='Backspace')press('back');else if(k==='Escape')press('clear')});
show();
